/* OOP Studio — vanilla JavaScript, works on GitHub Pages with zero build tooling. */
(() => {
  'use strict';
  const modules = window.CURRICULUM;
  const topics = modules.flatMap(m => m.topics.map(t => ({...t, moduleId:m.id, moduleTitle:m.title, moduleNum:m.number})));
  const topicMap = new Map(topics.map(t => [t.id,t]));
  const moduleMap = new Map(modules.map(m => [m.id,m]));
  const caseMap = new Map(window.DESIGN_CASES.map(c => [c.id,c]));
  const STORAGE_KEY = 'oopstudio.progress.v1';
  const defaultState = () => ({ completed:[], bookmarks:[], reviews:{}, notes:{}, caseNotes:{}, mockNotes:{}, quizBest:0, quizzesTaken:0, recent:[] });
  let state = readState();
  let toastTimer;
  let interval;
  const ui = { view:'overview', query:'', module:'all', status:'all', expanded:new Set(['foundations','relationships']), patternCat:'all', selectedCase:'parking', caseRevealed:{}, practiceTab:'quiz', quiz:null, quizModule:'all', quizLength:10, flashOrder:[], flashIndex:0, flashFlipped:false, mockTrack:'essentials', mockIndex:0, mockStarted:false, mockEnds:0, mockRemaining:0, language:'java' };
  const root = document.getElementById('view-root');
  const dlg = document.getElementById('topic-dialog');
  const dialogBody = document.getElementById('topic-dialog-body');
  const $ = sel => document.querySelector(sel);
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const count = m => m.topics.filter(t=>state.completed.includes(t.id)).length;
  const percent = (a,b)=>b?Math.round(a/b*100):0;
  const done = id => state.completed.includes(id);
  const bookmarked = id=>state.bookmarks.includes(id);
  const due = t => !!state.reviews[t.id] && state.reviews[t.id].due <= Date.now();
  const dueTopics = ()=>topics.filter(due);
  const nextTopic = () => topics.find(t => !done(t.id)) || topics[0];
  const total = topics.length;
  const completedTotal = () => state.completed.filter(id=>topicMap.has(id)).length;
  const metaCount = ()=>{const c=completedTotal();$('#sidebar-count').textContent=`${c}/${total}`;$('#side-progress-num').textContent=percent(c,total)+'%';$('#side-progress-fill').style.width=percent(c,total)+'%';$('#side-progress-caption').textContent=c===total?'Full checklist complete. Excellent work.':`${total-c} topics left in your checklist.`;};
  function readState(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!s||typeof s!=='object')return defaultState();let d=defaultState();for(const k of Object.keys(d)){if(Object.prototype.hasOwnProperty.call(s,k)&&typeof s[k]===typeof d[k])d[k]=s[k];}for(const k of ['completed','bookmarks','recent'])if(!Array.isArray(d[k]))d[k]=[];for(const k of ['reviews','notes','caseNotes','mockNotes'])if(!d[k]||Array.isArray(d[k]))d[k]={};return d;}catch{return defaultState();}}
  function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{showToast('Storage unavailable. Your progress may not persist.');}}
  function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
  function setDone(id, val){if(!topicMap.has(id))return;state.completed=state.completed.filter(x=>x!==id);if(val)state.completed.push(id);remember(id);save();metaCount();}
  function setBookmark(id,val){state.bookmarks=state.bookmarks.filter(x=>x!==id);if(val)state.bookmarks.push(id);save();}
  function remember(id){state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,16);save();}
  function statCard(num,label,foot,ico){return `<div class="stat-card card"><span class="stats-icon">${icon(ico)}</span><div class="stat-value">${esc(num)}</div><div class="stat-label">${esc(label)}</div><div class="stat-foot">${esc(foot)}</div></div>`;}
  function pageHeader(kicker,title,desc,actions=''){return `<div class="page-header"><div><div class="eyebrow">${esc(kicker)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-desc">${esc(desc)}</p></div>${actions}</div>`;}
  function moduleCard(m){const c=count(m), n=m.topics.length;return `<a href="#/syllabus" class="module-card card" data-module-open="${m.id}"><div class="module-head"><span class="module-num">MODULE ${m.number} &nbsp; / &nbsp; ${esc(m.accent.toUpperCase())}</span><span class="module-icon">${icon(['book','layers','target','cube','code','grid','zap','edit','spark','list'][+m.number-1])}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="module-progress"><div class="progress-track"><div class="progress-fill" style="width:${percent(c,n)}%"></div></div><span>${c}/${n}</span></div></a>`;}
  function renderOverview(){const c=completedTotal(),n=nextTopic(),bookmarks=state.bookmarks.filter(id=>topicMap.has(id)).length;
    return `<section class="hero"><div class="hero-copy"><div class="eyebrow light">YOUR SYSTEMS THINKING STARTS HERE <span style="margin-left:10px;color:#7f9180">— EST. TODAY</span></div><h1>Think in objects.<br><em>Design in systems.</em></h1><p>Go beyond definitions. Learn the trade-offs, practice real design problems, and walk into your next OOP interview prepared.</p><button class="btn btn-olive" data-action="continue">${icon('arrow')} Continue learning</button></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orb"></div><div class="orb"></div><div class="orb"></div></div><div class="hero-corner">10 MODULES / ONE CLEAR PATH</div></section>
    <section class="stats-grid" aria-label="Learning statistics">${statCard(`${percent(c,total)}%`,'Syllabus complete',`${c} of ${total} topics mastered`,'target')}${statCard(`${modules.length}`,'Focused modules','From fundamentals to UML','book')}${statCard('16','Design patterns','With use / avoid guidance','layers')}${statCard(`${dueTopics().length}`,'Cards due for review',`${bookmarks} topics bookmarked`,'rotate')}</section>
    <div class="section-line"><div><div class="tiny-overline">PICK UP WHERE YOU LEFT OFF</div><h2 class="mini-heading">Your next move</h2></div></div>
    <div class="dashboard-split"><section class="next-card card"><div class="eyebrow">UP NEXT &nbsp; • &nbsp; MODULE ${n.moduleNum}</div><h3>${esc(n.title)}</h3><p>${esc(n.definition).slice(0,150)}${n.definition.length>150?'…':''}</p><button class="btn btn-primary btn-small" data-topic="${n.id}">Study this concept ${icon('arrow')}</button></section><section class="sprint-card card"><div class="eyebrow">ACTIVE RECALL</div><h3>Make it stick.</h3><p>Challenge your understanding with interview-style questions, flashcards, and timed practice.</p><div class="sprint-meta"><span>${icon('clock')} &nbsp; 10 QUESTIONS</span><span>INSTANT FEEDBACK</span></div><button class="btn btn-outline btn-small" data-goto="practice">Enter practice room ${icon('arrow')}</button></section></div>
    <div class="section-line"><div><div class="tiny-overline">YOUR LEARNING MAP</div><h2 class="mini-heading">Explore the curriculum <span class="muted" style="font-size:13px;font-weight:500">/ ${modules.length} modules</span></h2></div><button class="section-link" data-goto="syllabus">Full checklist ${icon('arrow')}</button></div>
    <section class="module-grid">${modules.map(moduleCard).join('')}</section>
    <div class="insight-strip"><div class="insight-icon">${icon('info')}</div><div style="flex:1"><h3>A better way to prepare.</h3><p>For each topic: understand the rule, explain the example, name the failure mode, then defend your design decision.</p></div><button class="section-link" data-goto="design">Try a design challenge ${icon('arrow')}</button></div>`;
  }
  function topicRow(t){return `<div class="topic-row ${done(t.id)?'complete':''}"><input class="topic-check" data-complete="${t.id}" type="checkbox" aria-label="Mark ${esc(t.title)} mastered" ${done(t.id)?'checked':''}><button class="topic-click" data-topic="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.definition)}</span></button><span class="tag line">${t.moduleNum}</span><button class="bookmark-btn ${bookmarked(t.id)?'saved':''}" title="${bookmarked(t.id)?'Remove bookmark':'Bookmark topic'}" aria-label="${bookmarked(t.id)?'Remove bookmark':'Bookmark'} ${esc(t.title)}" data-bookmark="${t.id}">${icon('bookmark')}</button>${icon('arrow').replace('<svg','<svg class="row-arrow"')}</div>`;}
  function renderSyllabus(){const query=ui.query.trim().toLowerCase();let visible=0;const cards=modules.filter(m=>ui.module==='all'||ui.module===m.id).map(m=>{
    const listed=m.topics.filter(t=>{if(ui.status==='done'&&!done(t.id))return false;if(ui.status==='todo'&&done(t.id))return false;if(ui.status==='saved'&&!bookmarked(t.id))return false;if(!query)return true;return (t.title+' '+t.definition+' '+t.example+' '+m.title).toLowerCase().includes(query);});visible+=listed.length;if(!listed.length)return '';let opened=ui.expanded.has(m.id)||!!query;return `<details class="curriculum-section" data-section="${m.id}" ${opened?'open':''}><summary><span class="section-number">${m.number}</span><div class="section-title-block"><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p></div><div class="section-progress"><span>${count(m)} / ${m.topics.length}</span><div class="progress-track"><div class="progress-fill" style="width:${percent(count(m),m.topics.length)}%"></div></div></div>${icon('chevron').replace('<svg','<svg class="summary-chevron"')}</summary><div class="topic-list">${listed.map(topicRow).join('')}</div></details>`;}).join('');
    return `${pageHeader('THE COMPLETE PLAYBOOK','Your curriculum.',`Every item from the 10-part checklist is here, expanded with explanations, practical examples, pitfalls, and interview-ready answers.`, `<button class="btn btn-outline btn-small" data-action="expand-all">Expand all ${icon('chevron')}</button>`)}<div class="syllabus-note">${icon('info')} Tick the checkbox when you can explain a topic without notes. Click the title for the deeper breakdown.</div><div class="toolbar"><select id="module-filter" class="field" aria-label="Filter by module"><option value="all">All 10 modules</option>${modules.map(m=>`<option value="${m.id}" ${ui.module===m.id?'selected':''}>${m.number} · ${esc(m.title)}</option>`).join('')}</select><select id="status-filter" class="field" aria-label="Filter by status"><option value="all" ${ui.status==='all'?'selected':''}>All topics</option><option value="todo" ${ui.status==='todo'?'selected':''}>Not yet mastered</option><option value="done" ${ui.status==='done'?'selected':''}>Mastered</option><option value="saved" ${ui.status==='saved'?'selected':''}>Bookmarked</option></select><div class="toolbar-spacer"></div><span class="filter-count">${visible} TOPICS SHOWN / ${total} TOTAL</span><button class="btn btn-outline btn-small" data-action="collapse-all">Collapse all</button></div>${cards||`<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h3>No topics found</h3><p>Adjust your search or filters to see matching concepts.</p><button class="btn btn-soft" data-action="clear-filters">Clear filters</button></div>`}`;
  }
  function renderPatterns(){const groups=window.PATTERN_GROUPS, matches=topics.filter(t=>t.pattern&&(ui.patternCat==='all'||t.pattern.toLowerCase()===ui.patternCat));
    return `${pageHeader('THE PATTERN ATLAS','16 patterns. Better judgment.','Recognize the problem a pattern solves, the new complexity it introduces, and the simpler alternative you should consider first.')}
    <div class="segment-tabs"><button class="segment-btn ${ui.patternCat==='all'?'active':''}" data-pattern-cat="all">All patterns <span style="opacity:.55">16</span></button>${groups.map(g=>`<button class="segment-btn ${ui.patternCat===g.id?'active':''}" data-pattern-cat="${g.id}">${esc(g.name)} <span style="opacity:.55">${g.patternIds.length}</span></button>`).join('')}</div>
    <div class="patterns-grid">${matches.map(t=>`<article class="pattern-card card"><div class="pattern-top"><span class="tag">${esc(t.pattern)}</span><button class="bookmark-btn ${bookmarked(t.id)?'saved':''}" aria-label="Bookmark ${esc(t.title)}" data-bookmark="${t.id}">${icon('bookmark')}</button></div><h3>${esc(t.title)}</h3><p>${esc(t.definition)}</p><div class="pattern-use"><strong>USE WHEN &nbsp;→&nbsp;</strong> ${esc(t.when)}</div><button data-topic="${t.id}" class="section-link">Explore pattern ${icon('arrow')}</button></article>`).join('')}</div>
    <div class="section-line"><div><div class="tiny-overline">COMMON INTERVIEW FOLLOW-UPS</div><h2 class="mini-heading">Know the difference.</h2></div></div><div class="compare-grid">${window.COMPARISONS.map(c=>`<article class="compare-card card"><h3>${esc(c.title)}</h3><div class="compare-pills"><span class="tag">${esc(c.left)}</span><span class="tag line">vs</span><span class="tag">${esc(c.right)}</span></div><p>${esc(c.detail)}</p><small>${esc(c.example)}</small></article>`).join('')}</div>`;
  }
  function renderDesign(){const c=caseMap.get(ui.selectedCase)||window.DESIGN_CASES[0];const topic=topicMap.get(c.id);const marked=done(c.id);
    return `${pageHeader('WHITEBOARD PRACTICE','Design lab.','Ten guided object-oriented design challenges. Define responsibilities, justify relationships, anticipate failure cases, then compare your approach with a reference solution.')}
    <div class="design-layout"><nav class="case-menu" aria-label="Design challenges">${window.DESIGN_CASES.map(x=>`<button class="case-item ${x.id===c.id?'active':''}" data-case="${x.id}"><span class="case-monogram">${x.icon}</span><span>${esc(x.title)}</span>${done(x.id)?icon('check').replace('<svg','<svg class="case-check-icon"'):''}</button>`).join('')}</nav>
    <section class="case-main card"><div class="case-title-row"><div><span class="eyebrow">CASE STUDY &nbsp; / &nbsp; ${String(window.DESIGN_CASES.findIndex(x=>x.id===c.id)+1).padStart(2,'0')}</span><h2>${esc(c.title)}</h2></div><div class="case-meta"><span class="tag">${esc(c.difficulty)}</span><span class="tag line">${icon('clock')} ${esc(c.time)}</span></div></div><p class="case-brief">${esc(c.brief)}</p><div class="case-grid"><div><h3 class="case-subtitle">01 / Functional requirements</h3><ul class="clean-list">${c.requirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3 class="case-subtitle">02 / Core objects to consider</h3><div class="class-chips">${c.classes.map(x=>`<span class="class-chip"><b>${esc(x[0])}</b><small>${esc(x[1])}</small></span>`).join('')}</div></div></div>
    <div class="divider"></div><h3 class="case-subtitle">03 / Relationships & collaborators</h3><div class="relation-board">${c.relations.map(r=>`<div>${esc(r)}</div>`).join('')}</div>
    <div class="case-twist"><strong>${icon('zap')} INTERVIEWER TWIST</strong>${esc(c.twist)}</div>
    <div class="reveal-box"><h3 class="case-subtitle">04 / Architecture reasoning</h3>${ui.caseRevealed[c.id]?`<p class="reveal-answer">${esc(c.solution)}</p><p class="reveal-answer"><strong>Follow-up:</strong> ${esc(c.followup)}</p><button class="section-link" data-action="hide-case">Hide reference answer ${icon('chevron')}</button>`:`<p style="font-size:12px;color:#879780">Try your own design before opening the reference. What invariant matters most? Where is the abstraction boundary?</p><button class="btn btn-soft btn-small" data-action="reveal-case">Reveal reference reasoning ${icon('arrow')}</button>`}</div>
    <div class="divider"></div><h3 class="case-subtitle">05 / Your whiteboard notes</h3><textarea class="study-notes" data-case-note="${c.id}" placeholder="Responsibilities, invariants, design choices, edge cases, trade-offs...">${esc(state.caseNotes[c.id]||'')}</textarea><p class="notes-caption">Autosaved in your browser. Write your design before revealing the answer.</p><div class="case-actions"><button class="btn ${marked?'btn-soft':'btn-primary'}" data-action="mark-case">${icon('check')} ${marked?'Completed · Mark incomplete':'Mark challenge complete'}</button><button class="btn btn-outline" data-action="next-case">Next challenge ${icon('arrow')}</button><button class="btn btn-outline" data-topic="${c.id}">Concept notes ${icon('book')}</button></div></section></div>`;
  }
  function renderPractice(){return `${pageHeader('ACTIVE RECALL','The practice room.','Make retrieval a habit. Test concepts, rehearse clear explanations, and practice keeping your reasoning concise under a time limit.')}
    <div class="practice-nav"><button class="segment-btn ${ui.practiceTab==='quiz'?'active':''}" data-practice-tab="quiz">${icon('target')} Quiz mode</button><button class="segment-btn ${ui.practiceTab==='flash'?'active':''}" data-practice-tab="flash">${icon('layers')} Flashcards</button><button class="segment-btn ${ui.practiceTab==='mock'?'active':''}" data-practice-tab="mock">${icon('clock')} Mock interview</button></div>
    <section class="practice-panel">${ui.practiceTab==='quiz'?renderQuiz():ui.practiceTab==='flash'?renderFlash():renderMock()}</section>`;}
  function renderQuiz(){const q=ui.quiz;
    if(!q)return `<div class="practice-intro"><span class="tag">INTERVIEW SIMULATOR</span><h2>Can you defend the details?</h2><p>A mix of definitions, design trade-offs, language gotchas, and production scenarios. Choose an answer, then read the explanation before moving on. Each run is randomized.</p></div><div class="practice-controls"><label class="control-label">Question pool<select id="quiz-module" class="field"><option value="all">All modules</option>${modules.map(m=>`<option value="${m.id}" ${ui.quizModule===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><label class="control-label">Session length<select id="quiz-length" class="field"><option value="5" ${ui.quizLength===5?'selected':''}>5 questions</option><option value="10" ${ui.quizLength===10?'selected':''}>10 questions</option><option value="20" ${ui.quizLength===20?'selected':''}>20 questions</option><option value="42" ${ui.quizLength===42?'selected':''}>Full question bank</option></select></label><button class="btn btn-primary" data-action="start-quiz">Start session ${icon('arrow')}</button></div><div class="divider"></div><div class="small-meta">${window.QUESTION_BANK.length} QUESTIONS AVAILABLE &nbsp; / &nbsp; PERSONAL BEST ${state.quizBest}%</div>`;
    if(q.index>=q.questions.length){const correct=q.answers.filter(x=>x.correct).length,score=percent(correct,q.questions.length);return `<div class="quiz-result"><div class="eyebrow">SESSION COMPLETE</div><div class="result-score">${score}%</div><h2>${score>=80?'Strong work. Keep the momentum.':score>=50?'Good progress. Review the misses.':'Learn the gaps. Try again.'}</h2><p>You got ${correct} of ${q.questions.length} correct. Use the explanations to identify patterns in your mistakes.</p><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin:24px 0"><button class="btn btn-primary" data-action="start-quiz">New session ${icon('rotate')}</button><button class="btn btn-outline" data-action="reset-quiz">Adjust settings</button></div><div class="divider"></div><div style="text-align:left;max-width:630px;margin:auto"><h3 class="case-subtitle">REVIEW YOUR MISSES</h3>${q.answers.filter(x=>!x.correct).map(x=>`<div style="padding:13px 0;border-bottom:1px solid var(--line)"><strong style="font-size:12px">${esc(x.question.q)}</strong><p style="font-size:11px;color:#66765f;margin:7px 0 0">${esc(x.question.e)}</p></div>`).join('')||'<p class="muted">No missed questions this session.</p>'}</div></div>`;}
    const item=q.questions[q.index],sel=q.selected,submitted=q.submitted;
    return `<div class="quiz-heading"><span>QUESTION ${String(q.index+1).padStart(2,'0')} / ${String(q.questions.length).padStart(2,'0')}</span><span class="tag">${esc(moduleMap.get(item.m)?.title||'OOP')}</span><div class="progress-track"><div class="progress-fill" style="width:${percent(q.index+1,q.questions.length)}%"></div></div></div><h2 class="quiz-question">${esc(item.q)}</h2><div class="choices">${item.a.map((a,i)=>`<button class="choice ${sel===i?'active':''} ${submitted&&i===item.c?'correct':''} ${submitted&&sel===i&&i!==item.c?'incorrect':''}" data-choice="${i}" ${submitted?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>${submitted?`<div class="feedback ${sel===item.c?'':'bad'}"><strong>${sel===item.c?'Correct — here’s why.':'Not quite — here’s the distinction.'}</strong>${esc(item.e)}</div>`:''}<div class="quiz-actions"><span class="small-meta">${q.answers.filter(x=>x.correct).length} CORRECT SO FAR</span>${submitted?`<button class="btn btn-primary" data-action="next-question">${q.index===q.questions.length-1?'See results':'Next question'} ${icon('arrow')}</button>`:`<button class="btn btn-primary" data-action="submit-answer" ${sel===null?'disabled':''}>Check answer ${icon('check')}</button>`}</div>`;
  }
  function prepareFlash(){const overdue=dueTopics();const others=topics.filter(t=>!overdue.includes(t)&&!done(t.id));const mastered=topics.filter(t=>done(t.id)&&!overdue.includes(t));ui.flashOrder=[...shuffle(overdue),...shuffle(others),...shuffle(mastered)].map(t=>t.id);ui.flashIndex=0;ui.flashFlipped=false;}
  function renderFlash(){if(!ui.flashOrder.length)prepareFlash();const id=ui.flashOrder[ui.flashIndex%ui.flashOrder.length],t=topicMap.get(id);if(!t)return '<p>No flashcards found.</p>';return `<div class="flashcard-area"><div class="flash-top"><span>${icon('rotate')} &nbsp; ${dueTopics().length} CARDS DUE</span><span>CARD ${ui.flashIndex%ui.flashOrder.length+1} / ${ui.flashOrder.length}</span></div><button class="flash-card ${ui.flashFlipped?'flipped':''}" data-action="flip-card" aria-label="Flip flashcard"><span class="flash-label">${ui.flashFlipped?'BACK / THE EXPLANATION':'FRONT / EXPLAIN THIS'}</span><strong>${esc(ui.flashFlipped?t.answer:`What is ${t.title}?`)}</strong><span>${ui.flashFlipped?'Rate your recall below':'CLICK ANYWHERE TO REVEAL THE ANSWER'}</span></button><div class="flash-actions">${ui.flashFlipped?`<button class="btn btn-outline" data-action="flash-again">${icon('rotate')} Again / soon</button><button class="btn btn-soft" data-action="flash-good">${icon('check')} Got it / later</button>`:`<button class="btn btn-outline" data-action="flash-skip">Skip this card ${icon('arrow')}</button>`}</div><p class="notes-caption" style="text-align:center;margin-top:18px">“Again” schedules a near-term review; “Got it” increases the review interval. Progress is stored locally.</p></div>`;}
  function renderMock(){const track=window.INTERVIEW_TRACKS.find(t=>t.id===ui.mockTrack)||window.INTERVIEW_TRACKS[0],t=topicMap.get(track.topics[ui.mockIndex%track.topics.length]);let active=ui.mockStarted;return `<div class="mock-top"><div><span class="tag">SPEAK IT OUT LOUD</span><h2 class="mini-heading" style="margin-top:11px">Timed interview rehearsal</h2></div><div><div class="timer-clock" id="timer-display">${formatTime(active?ui.mockEnds-Date.now():ui.mockRemaining||track.minutes*60000)}</div><span class="small-meta">${active?'SESSION RUNNING':'READY TO START'}</span></div></div><p class="page-desc" style="margin:12px 0 0;font-size:12px">${esc(track.desc)}</p><div class="mock-options"><label class="control-label">Choose your track<select id="mock-track" class="field">${window.INTERVIEW_TRACKS.map(x=>`<option value="${x.id}" ${ui.mockTrack===x.id?'selected':''}>${esc(x.title)} · ${x.minutes}m</option>`).join('')}</select></label><button class="btn ${active?'btn-outline':'btn-primary'}" data-action="${active?'pause-mock':'start-mock'}">${active?'Pause session':'Start timer'} ${icon(active?'clock':'arrow')}</button><button class="btn btn-outline" data-action="reset-mock">Reset</button></div><div class="mock-question"><span class="small-meta">PROMPT ${ui.mockIndex+1} / ${track.topics.length} · ${esc(t.moduleTitle.toUpperCase())}</span><h3>${esc(t.title)} — explain it as if you’re speaking to an interviewer.</h3><p>Define it, give an example, point out the most common failure mode, and discuss when you would choose another approach.</p></div><h3 class="case-subtitle">Your talking points / preparation notes</h3><textarea id="mock-notes" class="mock-notes" placeholder="What would you say? Save bullet points, examples, and follow-up questions here.">${esc(state.mockNotes[t.id]||'')}</textarea><div class="quiz-actions"><button class="btn btn-outline" data-topic="${t.id}">See model answer ${icon('book')}</button><button class="btn btn-primary" data-action="next-mock">Next prompt ${icon('arrow')}</button></div><p class="notes-caption">The timer runs only while this page is open; refreshing or navigating away pauses the interview.</p>`;}
  function renderReview(){const saved=topics.filter(t=>bookmarked(t.id)),dueList=dueTopics();return `${pageHeader('YOUR PERSONAL STUDY SPACE','Saved & review.','Your bookmarks, spaced-review queue, and backup controls. All information remains in this browser unless you export it.')}
    <div class="review-split"><section class="review-section card"><div class="eyebrow">BOOKMARKED CONCEPTS</div><h3>${saved.length} saved topics</h3>${saved.length?saved.map(t=>`<div class="review-item"><button data-topic="${t.id}">${esc(t.title)}</button><span>${esc(t.moduleNum)}</span><button class="bookmark-btn saved" data-bookmark="${t.id}" aria-label="Unsave ${esc(t.title)}">${icon('bookmark')}</button></div>`).join(''):`<div class="empty-state"><h3>Nothing saved yet.</h3><p>Use the bookmark icon on any topic to keep it here for quick revision.</p><button class="btn btn-soft btn-small" data-goto="syllabus">Explore topics</button></div>`}</section>
    <section class="review-section card"><div class="eyebrow">SPACED REPETITION</div><h3>${dueList.length} cards due today</h3>${dueList.length?dueList.map(t=>`<div class="review-item"><button data-topic="${t.id}">${esc(t.title)}</button><span>Ready now</span></div>`).join(''):`<div class="empty-state"><h3>Review queue clear.</h3><p>Practice with flashcards, rate your recall, and future reviews will appear here automatically.</p><button class="btn btn-soft btn-small" data-action="review-flash">Study flashcards</button></div>`}</section></div>
    <div class="privacy-card"><div class="eyebrow">OWN YOUR PROGRESS</div><h3>Your data, your device.</h3><p>Completed topics, bookmarks, flashcard scheduling, quiz scores, and design notes are stored via your browser’s localStorage. Export a backup to move to another browser or computer.</p><div class="privacy-actions"><button class="btn btn-primary" data-action="export-progress">${icon('download')} Export backup</button><button class="btn btn-outline" data-action="import-progress">${icon('upload')} Import backup</button><button class="btn btn-outline danger" data-action="reset-progress">${icon('rotate')} Reset progress</button></div></div>`;}
  function render(){metaCount();$('#breadcrumb-current').textContent=({overview:'Overview',syllabus:'Curriculum',patterns:'Pattern atlas',design:'Design lab',practice:'Practice room',review:'Saved & review'})[ui.view]||'Overview';document.querySelectorAll('.nav-link').forEach(a=>{const on=a.dataset.route===ui.view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    const views={overview:renderOverview,syllabus:renderSyllabus,patterns:renderPatterns,design:renderDesign,practice:renderPractice,review:renderReview};root.innerHTML=(views[ui.view]||renderOverview)();}
  function goto(view){if(!['overview','syllabus','patterns','design','practice','review'].includes(view))return;closeMenu();if(ui.view==='practice'&&view!=='practice')pauseMock();ui.view=view;history.replaceState(null,'','#/'+view);render();window.scrollTo({top:0,behavior:'instant'});}
  function parseHash(){const match=(location.hash||'#/overview').match(/^#\/(overview|syllabus|patterns|design|practice|review)(?:\/.*)?$/);if(match){ui.view=match[1];render();closeMenu();if(dlg.open){dlg.close();document.body.classList.remove('dialog-open');}return;}const t=(location.hash||'').match(/^#\/topic\/([a-z0-9-]+)$/);if(t&&topicMap.has(t[1])){render();openTopic(t[1],false);return;}goto('overview');}
  function openTopic(id,writeHash=true){const t=topicMap.get(id);if(!t)return;const previousScroll=dlg.dataset.topicId===id?dialogBody.querySelector('.dialog-scroll')?.scrollTop||0:0;remember(id);dialogBody.innerHTML=renderTopic(t);dlg.dataset.topicId=id;if(!dlg.open)dlg.showModal();dialogBody.querySelector('.dialog-scroll').scrollTop=previousScroll;document.body.classList.add('dialog-open');if(writeHash)history.replaceState(null,'','#/topic/'+id);}
  function closeTopic(){if(dlg.open)dlg.close();document.body.classList.remove('dialog-open');if(location.hash.startsWith('#/topic/'))history.replaceState(null,'','#/'+ui.view);render();}
  const CODE_DEMOS={
    encapsulation:{java:'class BankAccount {\n  private long balance;\n\n  public void deposit(long amount) {\n    if (amount <= 0) throw new IllegalArgumentException();\n    balance += amount;\n  }\n\n  public long balance() { return balance; }\n}',python:'class BankAccount:\n    def __init__(self):\n        self._balance = 0\n\n    def deposit(self, amount):\n        if amount <= 0:\n            raise ValueError("positive amount required")\n        self._balance += amount',cpp:'class BankAccount {\n    long balance_ = 0;\npublic:\n    void deposit(long amount) {\n        if (amount <= 0) throw std::invalid_argument("amount");\n        balance_ += amount;\n    }\n};'},
    'overload-override':{java:'class Animal { void speak() { System.out.println("?"); } }\nclass Dog extends Animal {\n  @Override void speak() { System.out.println("Woof"); }\n}\nclass Printer {\n  void print(String value) { }\n  void print(int value) { }\n}',python:'class Animal:\n    def speak(self): return "?"\n\nclass Dog(Animal):\n    def speak(self): return "Woof"\n\n# Python has no native signature-based method overloading.',cpp:'struct Animal {\n    virtual void speak() {}\n    virtual ~Animal() = default;\n};\nstruct Dog : Animal {\n    void speak() override {}\n};'},
    'composition-over-inheritance':{java:'interface Channel { void send(String message); }\nclass NotificationService {\n  private final Channel channel;\n  NotificationService(Channel channel) {\n    this.channel = channel;\n  }\n  void notifyUser(String msg) { channel.send(msg); }\n}',python:'class NotificationService:\n    def __init__(self, channel):\n        self.channel = channel\n\n    def notify_user(self, message):\n        self.channel.send(message)',cpp:'struct Channel {\n    virtual void send(std::string_view) = 0;\n    virtual ~Channel() = default;\n};\nclass NotificationService {\n    Channel& channel_;\npublic:\n    explicit NotificationService(Channel& c) : channel_(c) {}\n    void notify(std::string_view s) { channel_.send(s); }\n};'},
    dip:{java:'interface PaymentProcessor { Receipt charge(Money amount); }\nclass CheckoutService {\n  private final PaymentProcessor payments;\n  CheckoutService(PaymentProcessor payments) {\n    this.payments = payments;\n  }\n  Receipt checkout(Money total) {\n    return payments.charge(total);\n  }\n}',python:'from typing import Protocol\n\nclass PaymentProcessor(Protocol):\n    def charge(self, amount: int) -> str: ...\n\nclass Checkout:\n    def __init__(self, processor: PaymentProcessor):\n        self.processor = processor',cpp:'struct PaymentProcessor {\n    virtual Receipt charge(Money) = 0;\n    virtual ~PaymentProcessor() = default;\n};\nclass Checkout {\n    PaymentProcessor& processor_;\npublic:\n    explicit Checkout(PaymentProcessor& p): processor_(p) {}\n};'},
    strategy:{java:'interface ShippingCost { int calculate(Order order); }\nclass StandardShipping implements ShippingCost {\n  public int calculate(Order o) { return 50; }\n}\nclass Checkout {\n  int total(Order o, ShippingCost strategy) {\n    return o.subtotal() + strategy.calculate(o);\n  }\n}',python:'from typing import Protocol\nclass ShippingCost(Protocol):\n    def calculate(self, order): ...\n\nclass Checkout:\n    def total(self, order, shipping):\n        return order.subtotal + shipping.calculate(order)',cpp:'struct ShippingCost {\n    virtual int calculate(const Order&) const = 0;\n    virtual ~ShippingCost() = default;\n};\nint total(const Order& o, const ShippingCost& cost) {\n    return o.subtotal() + cost.calculate(o);\n}'},
    observer:{java:'interface OrderListener { void onPlaced(Order o); }\nclass OrderEvents {\n  private final List<OrderListener> listeners = new ArrayList<>();\n  void subscribe(OrderListener listener) { listeners.add(listener); }\n  void publish(Order order) {\n    for (var listener : List.copyOf(listeners)) {\n      listener.onPlaced(order);\n    }\n  }\n}',python:'class OrderEvents:\n    def __init__(self): self.listeners = []\n    def subscribe(self, callback): self.listeners.append(callback)\n    def publish(self, order):\n        for callback in tuple(self.listeners):\n            callback(order)'},
    builder:{java:'HttpRequest req = HttpRequest.newBuilder()\n    .uri(URI.create("https://example.com"))\n    .timeout(Duration.ofSeconds(3))\n    .header("Accept", "application/json")\n    .GET()\n    .build();'},
    state:{java:'interface MachineState {\n  void insertCoin(VendingMachine machine, int amount);\n  void select(VendingMachine machine, String slot);\n  void dispense(VendingMachine machine);\n}\n// Each state implements only valid transitions;\n// invalid actions fail explicitly.'},
    singleton:{java:'enum Registry {\n  INSTANCE;\n  private final Map<String, String> config = Map.of();\n  String get(String key) { return config.get(key); }\n}\n// Thread-safe initialization does NOT make mutable fields safe.',cpp:'class Registry {\npublic:\n    static Registry& instance() {\n        static Registry singleton; // thread-safe since C++11\n        return singleton;\n    }\nprivate:\n    Registry() = default;\n};',python:'class Registry:\n    _instance = None\n    def __new__(cls):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n        return cls._instance\n# This naive check is not safe under concurrent initialization.'},
    'abstract-interface':{java:'interface Cacheable { void invalidate(); }\nabstract class BaseRepository {\n  protected final DataSource source;\n  protected BaseRepository(DataSource source) {\n    this.source = source;\n  }\n  abstract Object findById(long id);\n}'},
    'constructor-chaining':{java:'class User {\n  final String name;\n  final String role;\n  User(String name) { this(name, "member"); }\n  User(String name, String role) {\n    this.name = Objects.requireNonNull(name);\n    this.role = Objects.requireNonNull(role);\n  }\n}'},
    'thread-safety':{java:'class Inventory {\n  private int stock = 10;\n  synchronized boolean reserveOne() {\n    if (stock == 0) return false;\n    stock--;\n    return true;\n  }\n}\n// One operation protects the check + decrement together.'},
    immutability:{java:'record Money(long cents, String currency) {\n  Money {\n    Objects.requireNonNull(currency);\n  }\n  Money add(Money other) {\n    if (!currency.equals(other.currency()))\n      throw new IllegalArgumentException("currency mismatch");\n    return new Money(Math.addExact(cents, other.cents()), currency);\n  }\n}'},
    equality:{java:'record Money(long cents, String currency) {}\nvar a = new Money(500, "INR");\nvar b = new Money(500, "INR");\nSystem.out.println(a == b);      // false: distinct instances\nSystem.out.println(a.equals(b)); // true: value equality',python:'a = [1, 2]\nb = [1, 2]\nprint(a is b)  # False: not the same object\nprint(a == b)  # True: same list contents'},
    'uml-relationships':{java:'Order "1" ◆──── "1..*" OrderLine   // composition\nCheckoutService - - - > PaymentGateway  // dependency\nConcreteGateway - -▷ PaymentGateway     // realizes interface\nElectricCar ───▷ Vehicle                // inheritance'},
    'di-ioc':{java:'class OrderService {\n  private final OrderRepository repository;\n  OrderService(OrderRepository repository) {\n    this.repository = repository;\n  }\n}\n// Composition root — no framework required:\nvar repo = new SqlOrderRepository(dataSource);\nvar service = new OrderService(repo);'}
  };
  function renderRevision(t){
    const c=(window.REVISION_CHAPTERS||{})[t.id];
    if(!c)return '';
    const paragraphs=(items)=>items.map(item=>`<li>${esc(item)}</li>`).join('');
    return `<div class="revision-label"><span>THE DEEP DIVE</span><span>FULL REVISION · ${c.mechanics.length} STUDY STEPS</span></div>
    <nav class="revision-toc" aria-label="Revision chapter navigation"><a href="#rev-concept" data-revision-anchor="rev-concept">Concept</a><a href="#rev-mechanics" data-revision-anchor="rev-mechanics">How it works</a><a href="#rev-worked" data-revision-anchor="rev-worked">Walkthrough</a><a href="#rev-judgment" data-revision-anchor="rev-judgment">Trade-offs</a><a href="#rev-drills" data-revision-anchor="rev-drills">Self-check</a></nav>
    <section class="revision-section" id="rev-concept"><span class="revision-step">01 / UNDERSTAND</span><h3>The idea, properly explained</h3><p>${esc(c.concept)}</p></section>
    <section class="revision-section" id="rev-mechanics"><span class="revision-step">02 / BUILD THE MENTAL MODEL</span><h3>How it works, step by step</h3><ol class="revision-steps">${paragraphs(c.mechanics)}</ol></section>
    <section class="revision-section revision-walkthrough" id="rev-worked"><span class="revision-step">03 / APPLY IT</span><h3>Worked scenario</h3><p>${esc(c.worked)}</p></section>
    <section class="revision-section" id="rev-judgment"><span class="revision-step">04 / THINK LIKE AN ENGINEER</span><h3>When to use it — and when not to</h3><p>${esc(c.tradeoff)}</p></section>
    <section class="revision-section revision-drills" id="rev-drills"><span class="revision-step">05 / TEST YOUR UNDERSTANDING</span><h3>Interview follow-up questions</h3><ol>${paragraphs(c.drills)}</ol><p class="revision-tip">Try answering each out loud before looking at the summary below.</p></section></div>`;
  }
  function renderTopic(t){const notes=state.notes[t.id]||'',d=done(t.id),b=bookmarked(t.id),snippet=(CODE_DEMOS[t.id]||{})[ui.language],pat=!!t.pattern;
    return `<div class="topic-dialog-body"><div class="dialog-header"><span class="dialog-title-line">MODULE ${t.moduleNum} &nbsp; / &nbsp; ${esc(t.moduleTitle)}</span><div class="dialog-header-actions"><button class="dialog-expand" data-action="toggle-reader-size" aria-label="${dlg.classList.contains('is-expanded')?'Collapse to side panel':'Expand to full screen'}" aria-pressed="${dlg.classList.contains('is-expanded')}" title="${dlg.classList.contains('is-expanded')?'Collapse reader':'Expand reader'}">${icon(dlg.classList.contains('is-expanded')?'minimize':'maximize')}<span class="dialog-expand-label">${dlg.classList.contains('is-expanded')?'Collapse':'Expand'}</span></button><button class="dialog-close" data-action="close-topic" aria-label="Close topic">${icon('x')}</button></div></div><div class="dialog-scroll"><div class="dialog-overline"><span class="tag">${pat?esc(t.pattern):'CORE KNOWLEDGE'}</span>${d?'<span class="tag">✓ MASTERED</span>':''}</div><h2>${esc(t.title)}</h2><p class="dialog-lead">${esc(t.definition)}</p>${renderRevision(t)}<div class="revision-label revision-quick"><span>QUICK REVISION</span><span>RECAP &amp; REFERENCE</span></div><div class="dialog-section example-panel"><h3>01 / An example that makes it real</h3><p>${esc(t.example)}</p></div><div class="dialog-section pitfall-panel"><h3>02 / The trap to watch for</h3><p>${esc(t.trap)}</p></div><div class="dialog-section interview-answer"><h3>03 / A concise interview answer</h3><p>“${esc(t.answer)}”</p></div>
    ${pat?`<div class="dialog-section"><h3>When to reach for it</h3><p>${esc(t.when)}</p><h3 style="margin-top:17px">When not to use it</h3><p>${esc(t.avoid)}</p><h3 style="margin-top:17px">A practical implementation recipe</h3><p>${esc(t.recipe)}</p></div>`:''}
    ${CODE_DEMOS[t.id]?`<div class="dialog-section"><div style="display:flex;justify-content:space-between;align-items:center;gap:15px"><h3>04 / Implementation sketch</h3><select class="field" id="code-language" aria-label="Example programming language" style="height:33px;min-width:115px"><option value="java" ${ui.language==='java'?'selected':''}>Java</option><option value="cpp" ${ui.language==='cpp'?'selected':''}>C++</option><option value="python" ${ui.language==='python'?'selected':''}>Python</option></select></div>${snippet?`<div class="code-panel"><div class="code-head">${esc(ui.language.toUpperCase())} · ILLUSTRATIVE EXAMPLE <button class="copy-btn" data-action="copy-code" data-for="${t.id}">COPY CODE</button></div><pre><code>${esc(snippet)}</code></pre></div>`:`<p class="notes-caption">There isn't a ${esc(ui.language)} snippet for this topic yet. Switch language or use the explanation above.</p>`}</div>`:''}
    <div class="dialog-section prompt-area"><h3>05 / Say it out loud</h3><p>How would you explain ${esc(t.title.toLowerCase())} to an interviewer, show a concrete example, and justify when the idea is or isn't appropriate?</p><span class="notes-caption">Aim for a 60–90 second answer before checking the example response.</span></div>
    <div class="dialog-section"><h3>06 / Your personal notes</h3><textarea class="study-notes" data-topic-note="${t.id}" placeholder="Your own explanation, gotchas, or follow-up questions...">${esc(notes)}</textarea><p class="notes-caption">Notes save automatically on this device.</p></div></div><div class="dialog-footer"><button class="bookmark-btn ${b?'saved':''}" data-bookmark="${t.id}" title="Save this topic" aria-label="Bookmark topic">${icon('bookmark')}</button><button class="btn btn-outline" data-action="next-topic">Next topic ${icon('arrow')}</button><button class="btn ${d?'btn-soft':'btn-primary'}" data-action="toggle-topic-complete" data-id="${t.id}">${icon('check')} ${d?'Mastered ✓':'Mark as mastered'}</button></div></div>`;}
  function shuffle(arr){const out=[...arr];for(let i=out.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
  function startQuiz(){const pool=window.QUESTION_BANK.filter(q=>ui.quizModule==='all'||q.m===ui.quizModule);if(pool.length===0){showToast('No questions available for this module.');return;}ui.quiz={questions:shuffle(pool).slice(0,Math.min(ui.quizLength,pool.length)),index:0,selected:null,submitted:false,answers:[]};render();}
  function moveFlash(rating){const id=ui.flashOrder[ui.flashIndex%ui.flashOrder.length];if(rating){const r=state.reviews[id]||{interval:0,reps:0};if(rating==='good'){r.reps++;r.interval=r.interval===0?1:r.interval===1?3:Math.min(45,Math.round(r.interval*2.2));}else{r.reps=0;r.interval=0;r.due=Date.now()+10*60*1000;}if(rating==='good')r.due=Date.now()+r.interval*86400000;state.reviews[id]=r;save();}ui.flashIndex=(ui.flashIndex+1)%ui.flashOrder.length;ui.flashFlipped=false;render();}
  function formatTime(ms){let sec=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
  function updateTimer(){if(!ui.mockStarted)return;const left=Math.max(0,ui.mockEnds-Date.now()),el=$('#timer-display');if(el&&ui.view==='practice'&&ui.practiceTab==='mock')el.textContent=formatTime(left);if(left<=0){pauseMock();ui.mockRemaining=0;showToast('Your interview session has ended.');render();}}
  function pauseMock(){if(ui.mockStarted){ui.mockRemaining=Math.max(0,ui.mockEnds-Date.now());ui.mockStarted=false;}clearInterval(interval);}
  function closeMenu(){$('#shell').classList.remove('sidebar-open');$('#menu-toggle').setAttribute('aria-expanded','false');}
  function updateCurrentPanel(){if(dlg.open&&location.hash.startsWith('#/topic/')){const id=location.hash.split('/').pop();openTopic(id,false);}else render();}
  function downloadBlob(filename,data){const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  // Delegated events avoid a large library and still work after HTML is rerendered.
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-route]');if(nav){e.preventDefault();goto(nav.dataset.route);return;}
    if(e.target.closest('#menu-toggle')){const on=$('#shell').classList.toggle('sidebar-open');$('#menu-toggle').setAttribute('aria-expanded',String(on));return;}
    if(e.target.closest('#sidebar-backdrop')){closeMenu();return;}
    const anchor=e.target.closest('[data-revision-anchor]');if(anchor){e.preventDefault();const pane=anchor.closest('.dialog-scroll');const target=pane?.querySelector('#'+anchor.dataset.revisionAnchor);if(target){pane.scrollTo({top:target.offsetTop-pane.offsetTop-12,behavior:'smooth'});}return;}
    const open=e.target.closest('[data-topic]');if(open){e.preventDefault();openTopic(open.dataset.topic);return;}
    const book=e.target.closest('[data-bookmark]');if(book){const id=book.dataset.bookmark;setBookmark(id,!bookmarked(id));updateCurrentPanel();showToast(bookmarked(id)?'Topic bookmarked.':'Bookmark removed.');return;}
    const moduleLink=e.target.closest('[data-module-open]');if(moduleLink){e.preventDefault();ui.module=moduleLink.dataset.moduleOpen;ui.expanded.add(ui.module);goto('syllabus');return;}
    const go=e.target.closest('[data-goto]');if(go){goto(go.dataset.goto);return;}
    const cat=e.target.closest('[data-pattern-cat]');if(cat){ui.patternCat=cat.dataset.patternCat;render();return;}
    const caseSelect=e.target.closest('[data-case]');if(caseSelect){ui.selectedCase=caseSelect.dataset.case;render();return;}
    const tab=e.target.closest('[data-practice-tab]');if(tab){if(ui.practiceTab==='mock')pauseMock();ui.practiceTab=tab.dataset.practiceTab;render();return;}
    const choice=e.target.closest('[data-choice]');if(choice&&ui.quiz&&!ui.quiz.submitted){ui.quiz.selected=Number(choice.dataset.choice);render();return;}
    const act=e.target.closest('[data-action]');if(!act)return;
    const action=act.dataset.action;
    switch(action){
      case 'continue':openTopic(nextTopic().id);break;
      case 'expand-all':modules.forEach(m=>ui.expanded.add(m.id));render();break;
      case 'collapse-all':ui.expanded.clear();render();break;
      case 'clear-filters':ui.query='';ui.module='all';ui.status='all';$('#global-search').value='';render();break;
      case 'close-topic':closeTopic();break;
      case 'toggle-reader-size':{dlg.classList.toggle('is-expanded');const expanded=dlg.classList.contains('is-expanded');act.setAttribute('aria-pressed',String(expanded));act.setAttribute('aria-label',expanded?'Collapse to side panel':'Expand to full screen');act.title=expanded?'Collapse reader':'Expand reader';act.innerHTML=icon(expanded?'minimize':'maximize')+`<span class="dialog-expand-label">${expanded?'Collapse':'Expand'}</span>`;break;}
      case 'next-topic':{const id=location.hash.split('/').pop();let i=topics.findIndex(t=>t.id===id);openTopic(topics[(i+1)%topics.length].id);break;}
      case 'toggle-topic-complete':{const id=act.dataset.id;setDone(id,!done(id));openTopic(id,false);showToast(done(id)?'Marked as mastered.':'Moved back to study list.');break;}
      case 'copy-code':{const code=(CODE_DEMOS[act.dataset.for]||{})[ui.language]||'';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(code).then(()=>showToast('Code copied.')).catch(()=>showToast('Clipboard unavailable.'));else showToast('Clipboard unavailable.');break;}
      case 'reveal-case':ui.caseRevealed[ui.selectedCase]=true;render();break;
      case 'hide-case':ui.caseRevealed[ui.selectedCase]=false;render();break;
      case 'mark-case':setDone(ui.selectedCase,!done(ui.selectedCase));render();break;
      case 'next-case':{const i=window.DESIGN_CASES.findIndex(c=>c.id===ui.selectedCase);ui.selectedCase=window.DESIGN_CASES[(i+1)%window.DESIGN_CASES.length].id;render();break;}
      case 'start-quiz':startQuiz();break;
      case 'reset-quiz':ui.quiz=null;render();break;
      case 'submit-answer':{const q=ui.quiz;if(q&&q.selected!==null&&!q.submitted){q.submitted=true;const item=q.questions[q.index];q.answers.push({question:item,selected:q.selected,correct:q.selected===item.c});render();}break;}
      case 'next-question':{const q=ui.quiz;if(!q||!q.submitted)break;q.index++;q.selected=null;q.submitted=false;if(q.index===q.questions.length){state.quizzesTaken++;state.quizBest=Math.max(state.quizBest,percent(q.answers.filter(a=>a.correct).length,q.questions.length));save();}render();break;}
      case 'flip-card':ui.flashFlipped=!ui.flashFlipped;render();break;
      case 'flash-again':moveFlash('again');break;
      case 'flash-good':moveFlash('good');break;
      case 'flash-skip':moveFlash(null);break;
      case 'review-flash':ui.practiceTab='flash';prepareFlash();goto('practice');break;
      case 'start-mock':{const track=window.INTERVIEW_TRACKS.find(t=>t.id===ui.mockTrack);if(!ui.mockRemaining)ui.mockRemaining=track.minutes*60000;ui.mockEnds=Date.now()+ui.mockRemaining;ui.mockStarted=true;clearInterval(interval);interval=setInterval(updateTimer,250);render();break;}
      case 'pause-mock':pauseMock();render();break;
      case 'reset-mock':pauseMock();ui.mockRemaining=0;ui.mockIndex=0;render();break;
      case 'next-mock':{const track=window.INTERVIEW_TRACKS.find(t=>t.id===ui.mockTrack);ui.mockIndex=(ui.mockIndex+1)%track.topics.length;render();break;}
      case 'export-progress':downloadBlob(`oop-studio-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'oop-studio',version:1,exportedAt:new Date().toISOString(),state},null,2));showToast('Backup exported.');break;
      case 'import-progress':$('#import-file').click();break;
      case 'reset-progress':if(confirm('Reset ALL local progress, notes, bookmarks, and quiz scores? Export a backup first if you want to keep them.')){state=defaultState();save();prepareFlash();render();showToast('Local progress cleared.');}break;
    }
  });
  document.addEventListener('toggle',e=>{const el=e.target;if(el.matches?.('[data-section]')){if(el.open)ui.expanded.add(el.dataset.section);else ui.expanded.delete(el.dataset.section);}},true);
  document.addEventListener('change',e=>{
    const el=e.target;
    if(el.matches('[data-complete]')){setDone(el.dataset.complete,el.checked);render();return;}
    if(el.id==='module-filter'){ui.module=el.value;render();return;}
    if(el.id==='status-filter'){ui.status=el.value;render();return;}
    if(el.id==='quiz-module'){ui.quizModule=el.value;return;}
    if(el.id==='quiz-length'){ui.quizLength=Number(el.value);return;}
    if(el.id==='mock-track'){pauseMock();ui.mockTrack=el.value;ui.mockIndex=0;ui.mockRemaining=0;render();return;}
    if(el.id==='code-language'){ui.language=el.value;const id=location.hash.split('/').pop();openTopic(id,false);return;}
  });
  document.addEventListener('input',e=>{
    const el=e.target;
    if(el.id==='global-search'){ui.query=el.value;ui.module='all';if(ui.view!=='syllabus')goto('syllabus');else render();const q=$('#global-search');q.value=ui.query;try{q.setSelectionRange(ui.query.length,ui.query.length);}catch{}return;}
    if(el.matches('[data-topic-note]')){state.notes[el.dataset.topicNote]=el.value;save();return;}
    if(el.matches('[data-case-note]')){state.caseNotes[el.dataset.caseNote]=el.value;save();return;}
    if(el.id==='mock-notes'){const track=window.INTERVIEW_TRACKS.find(t=>t.id===ui.mockTrack);state.mockNotes[track.topics[ui.mockIndex%track.topics.length]]=el.value;save();return;}
  });
  $('#import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;if(f.size>2_000_000){showToast('Backup exceeds 2 MB.');return;}try{const data=JSON.parse(await f.text());if(data.app!=='oop-studio'||data.version!==1||!data.state||!Array.isArray(data.state.completed)||!Array.isArray(data.state.bookmarks))throw Error('bad backup');if(!confirm('Replace current local progress with this backup?'))return;const imported=data.state;const clean=defaultState();clean.completed=imported.completed.filter(id=>typeof id==='string'&&topicMap.has(id));clean.bookmarks=imported.bookmarks.filter(id=>typeof id==='string'&&topicMap.has(id));clean.recent=Array.isArray(imported.recent)?imported.recent.filter(id=>typeof id==='string'&&topicMap.has(id)).slice(0,16):[];for(const k of ['reviews','notes','caseNotes','mockNotes']){if(imported[k]&&typeof imported[k]==='object'&&!Array.isArray(imported[k]))for(const [id,v] of Object.entries(imported[k])){if((k==='caseNotes'&&caseMap.has(id))||((k==='notes'||k==='reviews'||k==='mockNotes')&&topicMap.has(id))){if(k==='reviews'&&v&&typeof v==='object'&&Number.isFinite(v.due)&&Number.isFinite(v.interval))clean[k][id]={due:v.due,interval:v.interval,reps:Number(v.reps)||0};else if(k!=='reviews'&&typeof v==='string')clean[k][id]=v.slice(0,100000);}}}clean.quizBest=Math.min(100,Math.max(0,Number(imported.quizBest)||0));clean.quizzesTaken=Math.max(0,Number(imported.quizzesTaken)||0);state=clean;save();prepareFlash();render();showToast('Backup imported.');}catch{showToast('Invalid OOP Studio backup file.');}});
  document.addEventListener('keydown',e=>{const target=e.target;if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(target.tagName)&&!dlg.open){e.preventDefault();$('#global-search').focus();}if(e.key==='Escape'&&dlg.open){e.preventDefault();closeTopic();}});
  dlg.addEventListener('click',e=>{if(e.target===dlg)closeTopic();});
  dlg.addEventListener('cancel',e=>{e.preventDefault();closeTopic();});
  window.addEventListener('hashchange',parseHash);
  parseHash();
})();
